package app.dayflow;
import android.os.*;
import android.text.*;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import com.google.android.material.chip.*;
import com.google.android.material.card.MaterialCardView;
import com.google.android.material.materialswitch.MaterialSwitch;
import com.google.android.material.textfield.TextInputEditText;
import org.json.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

/** Secondary management pages keep the home screen strictly about today. */
public final class PlanHub {
    public static void show(MainActivity a){LinearLayout page=a.fullPage("全部安排",a::home);page.addView(Ui.text(a,"全部安排",24,true));page.addView(Ui.button(a,"全局搜索与分类",true,()->search(a,"",null,0)));page.addView(Ui.button(a,"近期展开 / 远期折叠",false,()->FuturePlans.show(a)));page.addView(Ui.button(a,"长任务与阶段进度",false,()->search(a,"","project",0)));page.addView(Ui.button(a,"集中管理提醒",false,()->reminders(a,0)));page.addView(Ui.button(a,"日 / 周 / 月 / 年日历",false,()->calendar(a,LocalDate.now(),a.prefs.getString("calendar_view","week"))));page.addView(Ui.button(a,"新建长任务",false,()->a.newRecord("project")));page.addView(Ui.button(a,"管理任务类型",false,()->TaskTypes.show(a)));page.addView(Ui.button(a,"快速添加待办",false,()->quick(a)));page.addView(Ui.button(a,"AI 自然语言新建",false,()->ai(a)));page.addView(Ui.button(a,"浏览与启动偏好",false,()->preferences(a)));}
    public static void search(MainActivity a,String query,String kind,int offset){
        LinearLayout page=a.fullPage("搜索全部内容",()->show(a));TextInputEditText input=Ui.field(a,page,"搜索标题、正文、类型、地点",query,false);input.setSingleLine(true);input.setImeOptions(EditorInfo.IME_ACTION_SEARCH);ChipGroup filter=new ChipGroup(a);String[] labels={"全部","日程","长任务","待办","笔记","课程","通知"},kinds={null,"event","project","task","note","course","inbox"};filter.setSingleSelection(true);filter.setSelectionRequired(true);for(int i=0;i<labels.length;i++){String value=kinds[i];Chip chip=new Chip(a);chip.setText(labels[i]);chip.setCheckable(true);chip.setChecked(Objects.equals(value,kind));chip.setOnClickListener(v->search(a,input.getText().toString(),value,0));filter.addView(chip);}page.addView(filter);
        LinearLayout results=Ui.column(a);page.addView(results);final JSONObject[] first={null};Runnable load=()->{try{String text=input.getText().toString().trim();JSONArray records=Data.get(a).business(text,kind,offset);results.removeAllViews();first[0]=null;for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);if(first[0]==null)first[0]=r;MaterialCardView card=Ui.card(a);LinearLayout body=a.recordContents(r);body.addView(Ui.help(a,TaskTypes.label(a,r.optString("type_id"))+(PlanTime.cancelled(r)?" · 已取消":r.optString("completed").isEmpty()?"":" · 已完成")));card.addView(body);card.setOnClickListener(v->a.detail(r));results.addView(card);}if(records.length()==0)results.addView(Ui.help(a,"没有找到内容"));if(offset>0)results.addView(Ui.button(a,"上一页",false,()->search(a,text,kind,Math.max(0,offset-60))));if(records.length()==60)results.addView(Ui.button(a,"下一页",false,()->search(a,text,kind,offset+60)));}catch(Exception e){a.message(e.getMessage());}};
        Handler handler=new Handler(Looper.getMainLooper());input.addTextChangedListener(new TextWatcher(){Runnable pending;public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable s){if(pending!=null)handler.removeCallbacks(pending);pending=()->{if(input.isAttachedToWindow())load.run();};handler.postDelayed(pending,200);}public void onTextChanged(CharSequence s,int st,int before,int count){}});input.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH){if(first[0]!=null)a.detail(first[0]);return true;}return false;});load.run();
    }
    public static void relations(MainActivity a,LinearLayout page,JSONObject r){try{
        if(!r.optString("parent_id").isEmpty()){JSONObject parent=Data.get(a).find(r.optString("parent_id"));if(parent!=null&&!parent.optBoolean("deleted"))page.addView(Ui.button(a,"所属长任务 · "+parent.optString("title"),false,()->a.detail(parent)));}
        if(!r.optString("series_id").isEmpty()){JSONObject series=Data.get(a).find(r.optString("series_id"));if(series!=null)page.addView(Ui.button(a,"查看重复系列",false,()->a.detail(series)));}
        if(!r.optString("kind").equals("project"))return;JSONArray children=Data.get(a).childrenPage(r.optString("id"),0);int[] counts=Data.get(a).projectProgress(r.optString("id"));int total=counts[0],done=counts[1];
        page.addView(Ui.text(a,"阶段进度 · "+done+" / "+total,18,true));com.google.android.material.progressindicator.LinearProgressIndicator progress=new com.google.android.material.progressindicator.LinearProgressIndicator(a);progress.setMax(Math.max(1,total));progress.setProgress(done);page.addView(progress,new LinearLayout.LayoutParams(-1,Ui.dp(a,6)));
        for(int i=0;i<children.length();i++){JSONObject child=children.getJSONObject(i);if(child.optString("kind").equals("type"))continue;page.addView(Ui.button(a,(child.optString("completed").isEmpty()?"○ ":"✓ ")+child.optString("title")+(PlanTime.cancelled(child)?" · 已取消":""),false,()->a.detail(child)));}
        if(children.length()==40)page.addView(Ui.button(a,"查看全部子任务",false,()->ProjectChildren.show(a,r,0)));
        page.addView(Ui.button(a,"＋ 添加子任务",false,()->{try{a.edit(Data.make("task","").put("parent_id",r.optString("id")));}catch(Exception e){a.message(e.getMessage());}}));
    }catch(Exception e){a.message(e.getMessage());}}
    private static void quick(MainActivity a){LinearLayout page=a.fullPage("快速待办",()->show(a));TextInputEditText title=Ui.field(a,page,"写下待办，回车添加","",false),due=Ui.field(a,page,"截止日期（可选，YYYY-MM-DD）","",false);Runnable save=()->{try{if(title.getText().toString().trim().isEmpty())throw new Exception("请填写标题");JSONObject r=Data.make("task",title.getText().toString().trim()).put("due_date",due.getText().toString().trim());Data.validate(r);Data.get(a).save(r);a.changed();title.setText("");a.message("已添加待办");}catch(Exception e){a.message(e.getMessage());}};title.setSingleLine(true);title.setImeOptions(EditorInfo.IME_ACTION_DONE);title.setOnEditorActionListener((v,id,event)->{if(id==EditorInfo.IME_ACTION_DONE){save.run();return true;}return false;});page.addView(Ui.button(a,"添加",true,save));page.addView(Ui.button(a,"查看全部待办",false,()->a.tasks()));}
    private static void ai(MainActivity a){LinearLayout page=a.fullPage("AI 新建",()->show(a));TextInputEditText text=Ui.field(a,page,"描述想要安排的事情","",true);page.addView(Ui.help(a,"例如：每周一三五早上7:30背单词；考研数学复习持续到12月20日。识别结果先生成待确认草稿。"));page.addView(Ui.button(a,"生成待确认日程",true,()->{try{if(text.getText().toString().trim().isEmpty())throw new Exception("请填写描述");a.aiScreen(Data.make("inbox","自然语言安排").put("content",text.getText().toString()));}catch(Exception e){a.message(e.getMessage());}}));}
    private static void reminders(MainActivity a,int mode){ReminderCenter.show(a,mode,0);}
    public static void calendar(MainActivity a,LocalDate date,String mode){
        if(mode.equals("month")){MonthBrowser.show(a,date,d->DailyTasks.show(a,d));return;}
        LinearLayout page=a.fullPage("日历",()->show(a));ChipGroup views=new ChipGroup(a);for(String value:new String[]{"day","week","month","year"}){Chip chip=new Chip(a);chip.setText(value.equals("day")?"日":value.equals("week")?"周":value.equals("month")?"月":"年");chip.setCheckable(true);chip.setChecked(value.equals(mode));chip.setOnClickListener(v->{a.prefs.edit().putString("calendar_view",value).apply();calendar(a,date,value);});views.addView(chip);}page.addView(views);
        if(mode.equals("year")){page.addView(Ui.text(a,date.getYear()+"年",24,true));LinearLayout nav=Ui.row(a);nav.addView(Ui.button(a,"上一年",false,()->calendar(a,date.minusYears(1),"year")),new LinearLayout.LayoutParams(0,-2,1));nav.addView(Ui.button(a,"下一年",false,()->calendar(a,date.plusYears(1),"year")),new LinearLayout.LayoutParams(0,-2,1));page.addView(nav);YearOverview.add(a,page,date);page.addView(Ui.button(a,"打印本年日程 / 保存 PDF",false,()->CalendarPrint.show(a,LocalDate.of(date.getYear(),1,1),LocalDate.of(date.getYear()+1,1,1))));return;}
        boolean week=mode.equals("week");LocalDate from=week?date.with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)):date;page.addView(Ui.text(a,from.toString()+(week?" 起的一周":""),22,true));LinearLayout nav=Ui.row(a);nav.addView(Ui.button(a,"上一"+(week?"周":"天"),false,()->calendar(a,date.minusDays(week?7:1),mode)),new LinearLayout.LayoutParams(0,-2,1));nav.addView(Ui.button(a,"今天",false,()->calendar(a,LocalDate.now(),mode)),new LinearLayout.LayoutParams(0,-2,1));nav.addView(Ui.button(a,"下一"+(week?"周":"天"),false,()->calendar(a,date.plusDays(week?7:1),mode)),new LinearLayout.LayoutParams(0,-2,1));page.addView(nav);
        for(int i=0;i<(week?7:1);i++){LocalDate day=from.plusDays(i);page.addView(Ui.button(a,day.format(DateTimeFormatter.ofPattern("M月d日 EEEE",Locale.CHINA)),false,()->DailyTasks.show(a,day)));try{JSONArray rows=Data.get(a).dayTasks(day);int count=0;for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);if(!a.prefs.getBoolean("show_projects",true)&&r.optString("kind").equals("project"))continue;if(!a.prefs.getBoolean("show_due",true)&&r.optString("start_at").isEmpty())continue;MaterialCardView card=Ui.card(a);card.addView(a.recordContents(r));card.setOnClickListener(v->a.detail(r));page.addView(card);count++;}if(count==0)page.addView(Ui.help(a,"暂无安排"));}catch(Exception e){a.message(e.getMessage());}}
        page.addView(Ui.button(a,"打印 / 保存 PDF",false,()->CalendarPrint.show(a,from,from.plusDays(week?7:1))));
        page.addView(Ui.button(a,"用表格编辑本周",false,()->ScheduleEditor.show(a,from,false)));
    }
    private static void preferences(MainActivity a){LinearLayout page=a.fullPage("浏览偏好",()->show(a));String[] starts={"today","note","inbox","course","settings","manage"};Spinner start=TaskTypes.spinner(a,page,"启动页面",Arrays.asList("今天","笔记","收集箱","课表","设置","全部安排"));for(int i=0;i<starts.length;i++)if(starts[i].equals(a.prefs.getString("start_page","today")))start.setSelection(i);String[] modes={"week","day","month","year"};Spinner view=TaskTypes.spinner(a,page,"默认日历视图",Arrays.asList("周","日","月","年"));for(int i=0;i<modes.length;i++)if(modes[i].equals(a.prefs.getString("calendar_view","week")))view.setSelection(i);MaterialSwitch projects=new MaterialSwitch(a);projects.setText("日历显示长任务");projects.setChecked(a.prefs.getBoolean("show_projects",true));page.addView(projects);MaterialSwitch due=new MaterialSwitch(a);due.setText("日历显示待办截止日期");due.setChecked(a.prefs.getBoolean("show_due",true));page.addView(due);page.addView(Ui.button(a,"保存偏好",true,()->{a.prefs.edit().putString("start_page",starts[start.getSelectedItemPosition()]).putString("calendar_view",modes[view.getSelectedItemPosition()]).putBoolean("show_projects",projects.isChecked()).putBoolean("show_due",due.isChecked()).apply();a.message("已保存，仅影响本机");}));}
}
